    // The <svg> tag for one emoji, or null when the emoji has no line icon
    public static function svg(string $emoji): ?string
    {
        $paths = self::ICONS[$emoji] ?? self::ICONS[$emoji . "\u{FE0F}"] ?? self::ICONS[str_replace("\u{FE0F}", '', $emoji)] ?? null;

        return $paths === null ? null
            : '<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $paths . '</svg>';
    }

    // A regular expression that finds every emoji in the list (longest first, so "⚠️" wins over "⚠")
    public static function pattern(): string
    {
        $emoji = array_keys(self::ICONS);
        usort($emoji, fn ($a, $b) => strlen($b) - strlen($a));

        return '/(?:' . implode('|', array_map(fn ($e) => preg_quote($e, '/'), $emoji)) . ')\x{FE0F}?/u';
    }
}
